INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23001, 'Matthew 26:66', 'Matthew', 26, 66, '&nbsp;ستاسو فېصله څۀ ده؟“ هغوئ جواب ورکړو چې، ”دے مجرم دے او د قتلولو جوګه دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23002, 'Matthew 26:67', 'Matthew', 26, 67, '&nbsp;بيا هغوئ د هغۀ په مخ وتُوکل او په سوکونو يې ووهلو او ځينو په څپېړو ووهلو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23003, 'Matthew 26:68', 'Matthew', 26, 68, '&nbsp;او وئيل يې، ”اے مسيح، کۀ تۀ په رښتيا نبى يې نو دا راته ووايه چې چا ووهلې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23004, 'Matthew 26:69', 'Matthew', 26, 69, '&nbsp;نو په دې دوران کښې پطروس بهر په صحن کښې ناست وو چې يوه وينځه ورغله او ورته يې ووئيل، ”تۀ خو هم د عيسىٰ ګليلى سره وې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23005, 'Matthew 26:70', 'Matthew', 26, 70, '&nbsp;خو پطروس د ټولو په مخکښې منکر شو او وې وئيل چې، ”زۀ نۀ پوهېږم، چې دا تاسو څۀ وايئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23006, 'Matthew 26:71', 'Matthew', 26, 71, '&nbsp;بيا هغه د ډيوډۍ په لور روان شو او هلته يوې بلې وينځې چې هغه وليدو نو موجودو خلقو ته يې ووئيل چې، ”دا سړے هم د عيسىٰ ناصرى سره وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23007, 'Matthew 26:72', 'Matthew', 26, 72, '&nbsp;يو ځل بيا هغه منکر شو او په قسمونو شو چې، ”زۀ دا سړے نۀ پېژنم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23008, 'Matthew 26:73', 'Matthew', 26, 73, '&nbsp;لږه شېبه وروستو د ولاړو کسانو نه يو څو کسان راغلل او پطروس ته يې ووئيل چې، ”بې‌شکه تۀ د هغوئ نه يو يې ځکه چې ستا د لهجې نه دا پته لګى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23009, 'Matthew 26:74', 'Matthew', 26, 74, '&nbsp;په دې هغه په بدو ردو سر شو او قسمونه يې وخوړل چې، ”زۀ دا سړے نۀ پېژنم.“ په دغه وخت کښې چرګ بانګ ووئيلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23010, 'Matthew 26:75', 'Matthew', 26, 75, '&nbsp;او پطروس ته د عيسىٰ هغه خبره راياده شوه چې فرمائيلى يې وُو چې، ”د چرګ د بانګ نه مخکښې به تۀ زما نه درې ځله اِنکارى شې.“ هغه بهر ووتو او په چغو چغو يې وژړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23011, 'Matthew 27:1', 'Matthew', 27, 1, '&nbsp;چې سبا شو نو مشران اِمامان او د قوم مشران راټول شول او دا منصوبه يې جوړه کړه چې عيسىٰ به څنګه وژنو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23012, 'Matthew 27:2', 'Matthew', 27, 2, '&nbsp;بيا يې هغه وتړلو او روان يې کړو او رومى ګورنر پيلاطوس ته يې حواله کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23013, 'Matthew 27:3', 'Matthew', 27, 3, '&nbsp;کله چې يهوداه مُخبر ته پته ولګېده چې په عيسىٰ باندې جرم ثابت شوے دے نو هغه پښېمانه شو او هغه د سپينو زرو دېرش سيکې يې مشرانو اِمامانو او قومى مشرانو ته واپس کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23014, 'Matthew 27:4', 'Matthew', 27, 4, '&nbsp;هغۀ ووئيل، ”ما ګناه کړې ده چې يو بې‌ګناه سړى ته د مرګ سزا مِلاو شوې ده.“ خو هغوئ ووئيل چې، ”زمونږ پرې څۀ؟ تۀ پوهه شه او ستا کار پوهه شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23015, 'Matthew 27:5', 'Matthew', 27, 5, '&nbsp;نو هغۀ بيا د سپينو زرو سيکې د خُدائ په کور کښې په زمکه وغورزولې او د هغوئ نه روان شو، او خپل ځان يې پانسى کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23016, 'Matthew 27:6', 'Matthew', 27, 6, '&nbsp;مشرانو اِمامانو د سپينو زرو سيکې راوچتې کړې او وې وئيل چې، ”دا سيکې د خُدائ د کور په خزانه کښې اچول روا نۀ دى ځکه چې دا د قتل قيمت دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23017, 'Matthew 27:7', 'Matthew', 27, 7, '&nbsp;نو صلاح يې وکړه او د کُلال زمکه يې پرې واخسته چې د مسافرو قبرستان پرې جوړ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23018, 'Matthew 27:8', 'Matthew', 27, 8, '&nbsp;تر نن ورځې پورې هغه زمکه د خُون په پټى ياديږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23019, 'Matthew 27:9', 'Matthew', 27, 9, '&nbsp;دغه شان د يرمياه نبى پېشګوئې تر سره شوه چې، ”هغوئ دېرش د سپينو زرو سيکې واخستلې چې هغه په بنى اِسرائيلو کښې د سر قيمت وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23020, 'Matthew 27:10', 'Matthew', 27, 10, '&nbsp;او هغه د سپينو زرو سيکې يې د کُلال په زمکه ورکړې، لکه چې مالِک ما ته حُکم راکړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23021, 'Matthew 27:11', 'Matthew', 27, 11, '&nbsp;بيا يې عيسىٰ ګورنر له راوستو او چې هغه هلته ودرېدو نو ګورنر ترې تپوس وکړو چې، ”ولې تۀ د يهوديانو بادشاه يې څۀ؟“ عيسىٰ وفرمائيل چې، ”دا ستا وينا ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23022, 'Matthew 27:12', 'Matthew', 27, 12, '&nbsp;او کوم اِلزام چې په هغۀ باندې مشرانو اِمامانو او اولسى مشرانو لګولے وو د هغې يې هيڅ جواب ورنۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23023, 'Matthew 27:13', 'Matthew', 27, 13, '&nbsp;بيا پيلاطوس ورته ووئيل چې، ”ولې تۀ دا ټولې ګواهۍ چې ستا په خلاف کيږى نۀ اورې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23024, 'Matthew 27:14', 'Matthew', 27, 14, '&nbsp;خو هغۀ په جواب کښې د يو ټکى نه هم اِنکار ونۀ کړو او ګورنر په دې ډېر حېران شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23025, 'Matthew 27:15', 'Matthew', 27, 15, '&nbsp;د اختر په ورځ د ګورنر دا دستور وو چې د خلقو په خوښه به يې يو قېدى آزادولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23026, 'Matthew 27:16', 'Matthew', 27, 16, '&nbsp;په دغه وخت کښې برابا نومې يو بدنام سړے په قېد کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23027, 'Matthew 27:17', 'Matthew', 27, 17, '&nbsp;کله چې خلق راغونډ شول نو پيلاطوس ورته ووئيل چې، ”ستاسو په خوښه زۀ څوک آزاد کړم، برابا يا عيسىٰ چې ورته مسيح وئيلے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23028, 'Matthew 27:18', 'Matthew', 27, 18, '&nbsp;ځکه چې هغۀ ته پته وه چې هغوئ عيسىٰ د حسد په وجه دۀ ته حواله کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23029, 'Matthew 27:19', 'Matthew', 27, 19, '&nbsp;پيلاطوس لا په تخت ناست وو چې د خپلې ښځې له طرفه ورته پېغام راغلو چې، ”دې بې‌ګناه سړى ته ګورے هيڅ ونۀ وائې ځکه چې بيګاه په ما په دې وجه په خوب کښې ډېر مصيبت تير شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23030, 'Matthew 27:20', 'Matthew', 27, 20, '&nbsp;تر دې وخته مشرانو اِمامانو او نورو مشرانو خلق دې ته لمسولى وُو چې د برابا آزادى وغواړى او د عيسىٰ قتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23031, 'Matthew 27:21', 'Matthew', 27, 21, '&nbsp;کله چې ګورنر دوباره ترې تپوس وکړو چې، ”په دواړو کښې څوک آزادول غواړئ؟“ هغوئ چغې کړې، ”برابا.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23032, 'Matthew 27:22', 'Matthew', 27, 22, '&nbsp;پيلاطوس ورته ووئيل چې، ”بيا د عيسىٰ سره څۀ وکړم څوک چې د مسيح په نوم ياديږى؟“ ټولو په يو آواز په چغو ووئيل چې، ”دے په سولۍ راځوړند کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23033, 'Matthew 27:23', 'Matthew', 27, 23, '&nbsp;پيلاطوس ووئيل چې، ”ولې؟ په څۀ ګناه؟“ خو هغوئ نورې هم چغې کړې چې، ”په سولۍ يې کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23034, 'Matthew 27:24', 'Matthew', 27, 24, '&nbsp;پيلاطوس پوهه شو چې زۀ هيڅ نۀ شم کولے او فساد جوړيږى، نو هغۀ اوبۀ راوخستلې، د ټولو خلقو په وړاندې يې خپل لاسونه ووينځل او وې وئيل چې، ”زما لاسونه دې د دې سړى د خُون نه پاک وى، د دۀ د خون ذمه وارى دې ستاسو په غاړه وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23035, 'Matthew 27:25', 'Matthew', 27, 25, '&nbsp;ټولو خلقو په يو آواز چغې کړې چې، ”د دۀ خُون دې زمونږ او زمونږ د اولاد په غاړه وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23036, 'Matthew 27:26', 'Matthew', 27, 26, '&nbsp;نو هغۀ بيا برابا آزاد کړو او عيسىٰ يې په کوړو ووهلو او په سولۍ کولو له يې ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23037, 'Matthew 27:27', 'Matthew', 27, 27, '&nbsp;بيا د ګورنر سپاهيانو عيسىٰ قلعې ته بوتلو او ټوله فوجى دسته يې ترې راچاپيره کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23038, 'Matthew 27:28', 'Matthew', 27, 28, '&nbsp;جامې يې ترې وويستلې او سره شان چُوغه يې پرې واچوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23039, 'Matthew 27:29', 'Matthew', 27, 29, '&nbsp;او د ازغو تاج يې جوړ کړو او ورته يې په سر کړو او يو بينت يې په ښى لاس کښې ورکړو، بيا د هغۀ په مخکښې په زنګنو شول او ټوقې يې ورپورې کولې چې، ”اے د يهوديانو بادشاه سلامت.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23040, 'Matthew 27:30', 'Matthew', 27, 30, '&nbsp;هغوئ په هغۀ وتُوکل او بينت يې ترې واخستو او په سر سر يې پرې ووهلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23041, 'Matthew 27:31', 'Matthew', 27, 31, '&nbsp;او چې ټوقې يې بس کړې نو چُوغه يې ترې وويستله او خپلې جامې يې ورواغوستلې. بيا يې هغه بهر په سولۍ کولو له بوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23042, 'Matthew 27:32', 'Matthew', 27, 32, '&nbsp;کله چې دوئ په لاره روان وُو نو شمعون نومې کرينى سړے يې په نظر شو او هغه يې په زور په بيګار راونيولو چې د عيسىٰ سولۍ يوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23043, 'Matthew 27:33', 'Matthew', 27, 33, '&nbsp;او بيا ګولګتا نومې ځائ ته ورغلل چې مطلب يې د کوپړو ځائ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23044, 'Matthew 27:34', 'Matthew', 27, 34, '&nbsp;هلته يې عيسىٰ ته د تريخ څيز سره ګډ کړى مے د څښلو دپاره ورکړل، خو د څَکلو نه وروستو يې ونۀ څښل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23045, 'Matthew 27:35', 'Matthew', 27, 35, '&nbsp;او چې کله يې دے په سولۍ وخېژولو نو د هغۀ په جامو يې پچه واچوله. او په خپلو کښې يې تقسيم کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23046, 'Matthew 27:36', 'Matthew', 27, 36, '&nbsp;نو بيا يې هلته څوکيدارۍ ته کښېناستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23047, 'Matthew 27:37', 'Matthew', 27, 37, '&nbsp;د هغۀ د سر دپاسه يې يوه تخته چې جرم پرې ليکلے شوے وو ټک وهله چې، دا د يهوديانو بادشاه عيسىٰ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23048, 'Matthew 27:38', 'Matthew', 27, 38, '&nbsp;دوه ډاکوان يې هم د هغۀ سره په سولۍ کړى وُو، يو يې د هغۀ ښى او بل يې د هغۀ ګس لاس ته راځوړند کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23049, 'Matthew 27:39', 'Matthew', 27, 39, '&nbsp;په لارې تېرېدونکو به عيسىٰ ته په چغو کنځل کول او په مسخرو به يې سرونه ورپورې خوځول،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23050, 'Matthew 27:40', 'Matthew', 27, 40, '&nbsp;”اوس ځان ته وګوره، تۀ به د خُدائ پاک دا کور ورانوې او بيا به يې په درېو ورځو کښې جوړوې. ښه نو بيا کۀ تۀ په رښتيا د خُدائ زوئ يې خپل ځان بچ کړه، او د دې سولۍ نه راکوز شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23051, 'Matthew 27:41', 'Matthew', 27, 41, '&nbsp;دغه شان مشرانو اِمامانو، د شرعې عالمانو او مشرانو هم ورپورې مسخرې کولې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23052, 'Matthew 27:42', 'Matthew', 27, 42, '&nbsp;او وئيل يې چې، ”هغۀ خو نور خلق بچ کول خو خپل ځان نۀ شى بچ کولے. بې‌شکه کۀ دے د بنى اِسرائيلو بادشاه وى نو اوس دې د دې سولۍ نه راکوز شى، نو بيا به پرې مونږ ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23053, 'Matthew 27:43', 'Matthew', 27, 43, '&nbsp;د دۀ په خُدائ پاک باور وو، اوس دې دے خُدائ بچ کړى کۀ هغه يې غواړى، ځکه چې دۀ وئيل چې، زۀ د خُدائ پاک زوئ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23054, 'Matthew 27:44', 'Matthew', 27, 44, '&nbsp;تر دې چې د دۀ سره په سولۍ شوو مجرمانو هم دۀ ته سپکې سپورې وئيلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23055, 'Matthew 27:45', 'Matthew', 27, 45, '&nbsp;د غرمې په وخت په ټوله زمکه تيارۀ راخوره شوه او د تير ماسپښين تر درېو بجو پورې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23056, 'Matthew 27:46', 'Matthew', 27, 46, '&nbsp;او په تير ماسپښين عيسىٰ په اوچت آواز نعرې کړې، ”ايلى، ايلى، لما شبقتنى؟“ يعنې، ”اے زما خُدايه پاکه، اے زما خُدايه پاکه، زۀ دې ولې پرېښودلم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23057, 'Matthew 27:47', 'Matthew', 27, 47, '&nbsp;ځينې ولاړو خلقو چې دا واورېدل نو وې وئيل چې، ”وګورئ دے اوس الياس ته نعرې وهى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23058, 'Matthew 27:48', 'Matthew', 27, 48, '&nbsp;په هغوئ کښې يو سمدستى منډه کړه يو اسفنج يې د سرکې نه ډک کړو او د هغۀ شونډو ته يې د يوې چوکې په سر ونيولو چې وې څښى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23059, 'Matthew 27:49', 'Matthew', 27, 49, '&nbsp;خو نورو ووئيل چې، ”اوس به وګورو چې الياس راشى او دے راکوز کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23060, 'Matthew 27:50', 'Matthew', 27, 50, '&nbsp;عيسىٰ بيا يوه تېزه کريکه کړه او ساه يې ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23061, 'Matthew 27:51', 'Matthew', 27, 51, '&nbsp;هغه وخت د خُدائ د کور پړده د سر نه تر بېخه پورې په مينځ دوه شوه. او زلزله راغله، ګټان وچاودل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23062, 'Matthew 27:52', 'Matthew', 27, 52, '&nbsp;او قبرونه وسپړدے شول او د خُدائ پاک ډېر مقدسين د خوبه رابېدار شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23063, 'Matthew 27:53', 'Matthew', 27, 53, '&nbsp;او د عيسىٰ د پاڅېدلو نه پس هغوئ د قبرونو نه راووتل، يروشلم ته ننوتل او ډېرو خلقو يې ننداره وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23064, 'Matthew 27:54', 'Matthew', 27, 54, '&nbsp;کله چې صوبه دار او د هغۀ سپاهيانو چې د عيسىٰ څوکيدارى يې کوله زلزله او دا ټول واقعات وليدل نو په هغوئ هيبت راغلو او وې وئيل، ”بې‌شکه چې دا سړے د خُدائ پاک زوئ وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23065, 'Matthew 27:55', 'Matthew', 27, 55, '&nbsp;ډيرې ښځې هم هلته موجودې وې او د لرې نه يې تماشه کوله. هغوئ د ګليل نه په عيسىٰ پسې خِدمت ته راغلې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23066, 'Matthew 27:56', 'Matthew', 27, 56, '&nbsp;په هغوئ کښې يوه مريم مګدلينى وه او بله د يعقوب او د يوسف مور مريم، او د زبدى د زامنو مور وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23067, 'Matthew 27:57', 'Matthew', 27, 57, '&nbsp;کله چې ماښام شو نو د ارمتيه يو مالداره سړے وو چې نوم يې يوسف وو او د عيسىٰ مريد وو، راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23068, 'Matthew 27:58', 'Matthew', 27, 58, '&nbsp;هغه پيلاطوس له ورغلو او د عيسىٰ لاش يې ترې وغوښتو او پيلاطوس حکم وکړو چې ور دې کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23069, 'Matthew 27:59', 'Matthew', 27, 59, '&nbsp;يوسف هغه لاش يوړو او په صفا کتان کښې يې ونغښتو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23070, 'Matthew 27:60', 'Matthew', 27, 60, '&nbsp;او هغۀ په خپل نوې غار کښې کېښودو کوم چې هغۀ په ګټ کښې کنستے وو. او يو لوئ کاڼے يې د قبر خولې ته راورغړولو او ترې لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23071, 'Matthew 27:61', 'Matthew', 27, 61, '&nbsp;او مريم مګدلينى او هغه بله مريم دواړه يې قبر ته مخامخ ناستې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23072, 'Matthew 27:62', 'Matthew', 27, 62, '&nbsp;په بله ورځ چې د سبت ورځ وه مشران اِمامان او نور فريسيان په جمع پيلاطوس له راغلل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23073, 'Matthew 27:63', 'Matthew', 27, 63, '&nbsp;او وې وئيل چې، ”صاحبه، مونږ ته ياد دى چې هغه فريبى چې لا ژوندے وو نو وئيلى يې وُو چې زۀ به په درېمه ورځ پورته کړے شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23074, 'Matthew 27:64', 'Matthew', 27, 64, '&nbsp;نو تۀ بيا دا حکم ورکړه چې تر درېو ورځو پورې دې د دغه قبر څوکيدارى وکړے شى. هسې نه چې د هغۀ مريدان راشى، لاش يې په غلا وباسى او بيا خلقو ته وائى چې هغه پورته کړے شوے دے، او آخرى فريب يې د وړومبى فريب نه ډېر بد وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23075, 'Matthew 27:65', 'Matthew', 27, 65, '&nbsp;پيلاطوس ورته ووئيل چې، ”ځئ لاړ شئ، سپاهيان ځان سره بوځئ. څنګه مو چې خوښه وى نو هغه شان سخته څوکيدارى يې وکړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23076, 'Matthew 27:66', 'Matthew', 27, 66, '&nbsp;نو هغوئ لاړل، او د قبر د خولې په کاڼى يې مهرونه ولګول او د څوکيدارۍ دپاره يې پرې سپاهيان مقرر کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23077, 'Matthew 28:1', 'Matthew', 28, 1, '&nbsp;د سبت ورځ تيره شوه او د اِتوار د ورځې سحر کېدونکے وو چې مريم مګدلينى او هغه بله مريم د قبر ليدو له راغلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23078, 'Matthew 28:2', 'Matthew', 28, 2, '&nbsp;ناګهانه يوه سخته زلزله راغله، د آسمان نه د مالِک خُدائ يوه فرښته راکوزه شوه، غار له راغله او هغه کاڼے يې ورغړولو او پرې کښېناسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23079, 'Matthew 28:3', 'Matthew', 28, 3, '&nbsp;مخ يې د برېښنا په شان ځلېدو او جامې يې لکه د واورو په شان سپينې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23080, 'Matthew 28:4', 'Matthew', 28, 4, '&nbsp;څوکيداران يې په ليدو د يرې نه په لړزېدو شول او لکه د مړو پرېوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23081, 'Matthew 28:5', 'Matthew', 28, 5, '&nbsp;فرښتې بيا ښځو ته وفرمائيل چې، ”مۀ يرېږئ، ما ته پته ده چې تاسو د عيسىٰ ليدو له راغلى يئ څوک چې په سولۍ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23082, 'Matthew 28:6', 'Matthew', 28, 6, '&nbsp;هغه دلته نشته، هغه بيا پورته کړے شوے دے لکه څنګه چې هغۀ فرمائيلى وُو. راشئ، هغه ځائ وګورئ چرته چې هغه پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23083, 'Matthew 28:7', 'Matthew', 28, 7, '&nbsp;نو بيا زر لاړې شئ او د هغۀ مريدان خبر کړئ چې هغه له مړو نه ژوندے پاڅولے شوے دے او ستاسو نه وړاندې ګليل ته روان دے، تاسو به يې هلته ووينئ. څۀ چې درته ما ووئيل هغه ياد ساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23084, 'Matthew 28:8', 'Matthew', 28, 8, '&nbsp;هغوئ د قبر نه په هيبت او خوشحالۍ لاړې او په منډه شوې چې مريدان خبر کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23085, 'Matthew 28:9', 'Matthew', 28, 9, '&nbsp;ناڅاپى عيسىٰ په لاره پرې پېښ شو او په هغوئ يې سلام واچولو. هغوئ ورغلې او د هغۀ پښې يې ونيولې او سجده يې ورته وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23086, 'Matthew 28:10', 'Matthew', 28, 10, '&nbsp;بيا عيسىٰ هغوئ ته وفرمائيل چې، ”يرېږئ مه، لاړې شئ او زما وروڼو له دا پېغام ورکړئ چې هغوئ دې ګليل ته لاړ شى، ما به هلته ووينى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23087, 'Matthew 28:11', 'Matthew', 28, 11, '&nbsp;ښځې لا په خپله لار تللې چې ځينې څوکيداران ښار ته ننوتل او مشرانو اِمامانو ته يې ټوله قيصه تيره کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23088, 'Matthew 28:12', 'Matthew', 28, 12, '&nbsp;بيا هغوئ مشران راغونډ کړل او صلاح يې وکړه. او مشرانو اِمامانو سپاهيانو ته غټ رشوت ورکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23089, 'Matthew 28:13', 'Matthew', 28, 13, '&nbsp;او ورته يې ووئيل چې، ”تاسو به دا ووايئ چې د شپې چې مونږ اودۀ شو نو د هغۀ مريدان راغلل او د هغۀ لاش يې پټ کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23090, 'Matthew 28:14', 'Matthew', 28, 14, '&nbsp;او ورسره يې دا هم ووئيل چې، ”کۀ دا خبر د ګورنر غوږو ته ورسېدو نو مونږ به د هغۀ سره خبره وکړو او تاسو ته به هيڅ نقصان نۀ درکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23091, 'Matthew 28:15', 'Matthew', 28, 15, '&nbsp;نو هغوئ پېسې واخستلې او څۀ چې ورته وئيلے شوى وُو هم هغه شان يې وکړل. دغه قيصه تر نن ورځې په يهوديانو کښې خوره ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23092, 'Matthew 28:16', 'Matthew', 28, 16, '&nbsp;يوولس مريدان د ګليل هغه غر ته روان شول د کوم چې عيسىٰ ورته د تللو دپاره فرمائيلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23093, 'Matthew 28:17', 'Matthew', 28, 17, '&nbsp;کله چې هغوئ هغه وليدو نو ورته په سجده شول خو ځينې شکمن وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23094, 'Matthew 28:18', 'Matthew', 28, 18, '&nbsp;بيا عيسىٰ ورغلو او ورته يې وفرمائيل چې، ”د آسمان او د زمکې ټول اختيار ما ته راکړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23095, 'Matthew 28:19', 'Matthew', 28, 19, '&nbsp;ځکه تاسو په زمکه خوارۀ شئ او ټول قومونه زما مريدان کړئ او د پلار، د زوئ او د روحُ القُدس په نامه ورته بپتسمه ورکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23096, 'Matthew 28:20', 'Matthew', 28, 20, '&nbsp;او دا تعليم ورکوئ چې په هغه ټولو خبرو عمل کوئ چې ما تاسو ته حکم کړے دے. او دا يقين ساتئ چې زۀ به تل او تر قيامته پورې تاسو سره يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23097, 'Mark 1:1', 'Mark', 1, 1, '&nbsp;دا د خُدائ پاک د زوئ د عيسىٰ مسيح د زيرى شروع ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23098, 'Mark 1:2', 'Mark', 1, 2, '&nbsp;لکه څنګه چې يشعياه نبى ليکلى دى چې، ”ګوره، زۀ خپل پېغمبر ستا نه وړاندې لېږم چې ستا مخې ته لاره تياره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23099, 'Mark 1:3', 'Mark', 1, 3, '&nbsp;په بيابان کښې د نعرې وهونکى آواز دے چې د مالِک خُدائ لاره جوړه کړئ او د هغۀ لارې نېغې کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23100, 'Mark 1:4', 'Mark', 1, 4, '&nbsp;او دغه شان په بيابان کښې بپتسمه ورکوونکے يحيىٰ راغے او دا بيان يې کولو چې، ”توبه ګار شئ او بپتسمه واخلئ او ستاسو ګناهونه به معاف شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');